const VAULT_DB = 'wersee-private-ai-v1';
const KEY_STORE = 'device-keys';
const ALGORITHM = 'AES-GCM';

type VaultKeyRecord = {
  userId: string;
  keyId: string;
  key: CryptoKey;
};

type PrivateEnvelope = {
  v: 'device-aes-gcm-v1';
  keyId: string;
  iv: string;
  ciphertext: string;
};

const sessionKeys = new Map<string, VaultKeyRecord>();

const bytesToBase64 = (bytes: Uint8Array) => {
  let binary = '';
  for (let offset = 0; offset < bytes.length; offset += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + 0x8000));
  }
  return btoa(binary);
};

const base64ToBytes = (value: string) =>
  Uint8Array.from(atob(value), (character) => character.charCodeAt(0));

const openVault = () => new Promise<IDBDatabase>((resolve, reject) => {
  const request = indexedDB.open(VAULT_DB, 1);
  request.onupgradeneeded = () => {
    if (!request.result.objectStoreNames.contains(KEY_STORE)) {
      request.result.createObjectStore(KEY_STORE, { keyPath: 'userId' });
    }
  };
  request.onsuccess = () => resolve(request.result);
  request.onerror = () => reject(request.error || new Error('Private AI vault is unavailable.'));
});

const readKey = async (userId: string) => {
  const database = await openVault();
  try {
    return await new Promise<VaultKeyRecord | null>((resolve, reject) => {
      const request = database.transaction(KEY_STORE, 'readonly').objectStore(KEY_STORE).get(userId);
      request.onsuccess = () => resolve((request.result as VaultKeyRecord | undefined) || null);
      request.onerror = () => reject(request.error || new Error('Private AI key could not be read.'));
    });
  } finally {
    database.close();
  }
};

const writeKey = async (record: VaultKeyRecord) => {
  const database = await openVault();
  try {
    await new Promise<void>((resolve, reject) => {
      const transaction = database.transaction(KEY_STORE, 'readwrite');
      transaction.objectStore(KEY_STORE).put(record);
      transaction.oncomplete = () => resolve();
      transaction.onerror = () => reject(transaction.error || new Error('Private AI key could not be saved.'));
    });
  } finally {
    database.close();
  }
};

const createKeyRecord = async (userId: string): Promise<VaultKeyRecord> => ({
  userId,
  keyId: crypto.randomUUID(),
  key: await crypto.subtle.generateKey({ name: ALGORITHM, length: 256 }, false, ['encrypt', 'decrypt']),
});

export async function getPrivateAiVaultKey(userId: string): Promise<VaultKeyRecord> {
  const cached = sessionKeys.get(userId);
  if (cached) return cached;

  try {
    const stored = await readKey(userId);
    if (stored?.key && stored.keyId) {
      sessionKeys.set(userId, stored);
      return stored;
    }
    const created = await createKeyRecord(userId);
    await writeKey(created);
    sessionKeys.set(userId, created);
    return created;
  } catch (reason) {
    console.warn('Persistent private AI vault unavailable; using an in-memory key for this session.', reason);
    const temporary = await createKeyRecord(userId);
    sessionKeys.set(userId, temporary);
    return temporary;
  }
}

export async function encryptPrivateAiPayload(userId: string, payload: unknown) {
  const record = await getPrivateAiVaultKey(userId);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const plaintext = new TextEncoder().encode(JSON.stringify(payload));
  const ciphertext = await crypto.subtle.encrypt({ name: ALGORITHM, iv }, record.key, plaintext);
  const envelope: PrivateEnvelope = {
    v: 'device-aes-gcm-v1',
    keyId: record.keyId,
    iv: bytesToBase64(iv),
    ciphertext: bytesToBase64(new Uint8Array(ciphertext)),
  };
  return JSON.stringify(envelope);
}

export async function decryptPrivateAiPayload<T>(userId: string, value: string): Promise<T> {
  const envelope = JSON.parse(value) as Partial<PrivateEnvelope>;
  if (
    envelope.v !== 'device-aes-gcm-v1' ||
    typeof envelope.keyId !== 'string' ||
    typeof envelope.iv !== 'string' ||
    typeof envelope.ciphertext !== 'string'
  ) {
    throw new Error('Unsupported private AI payload.');
  }
  const record = await getPrivateAiVaultKey(userId);
  if (record.keyId !== envelope.keyId) {
    throw new Error('This private AI entry belongs to another device key.');
  }
  const plaintext = await crypto.subtle.decrypt(
    { name: ALGORITHM, iv: base64ToBytes(envelope.iv) },
    record.key,
    base64ToBytes(envelope.ciphertext),
  );
  return JSON.parse(new TextDecoder().decode(plaintext)) as T;
}
