import { useEffect, useMemo, useState } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import { ChevronDown, Inbox, Loader2, Mail, Sparkles } from 'lucide-react';
import { useSearchParams } from 'react-router-dom';
import { supabase } from '../../lib/supabase';
import type { PublicDmSubmission } from '../../types/publicDm';

type Props = {
  userId?: string;
  visible: boolean;
  searchQuery: string;
  activeSubmissionId?: string | null;
  onOpenConversation: (submission: PublicDmSubmission) => void;
  onUnreadChange?: (count: number) => void;
};

const labelNames: Record<PublicDmSubmission['label'], string> = {
  collaboration: 'Collaboration',
  support: 'Support',
  question: 'Question',
  spam: 'Spam',
};

export const PublicDmInbox = ({
  userId,
  visible,
  searchQuery,
  activeSubmissionId,
  onOpenConversation,
  onUnreadChange,
}: Props) => {
  const [searchParams] = useSearchParams();
  const [submissions, setSubmissions] = useState<PublicDmSubmission[]>([]);
  const [loading, setLoading] = useState(false);
  const [collapsedCategories, setCollapsedCategories] = useState<Set<string>>(new Set());
  const [collapsedSubcategories, setCollapsedSubcategories] = useState<Set<string>>(new Set());

  const load = async () => {
    if (!userId) return;
    setLoading(true);
    const { data, error } = await supabase
      .from('public_dm_submissions')
      .select('*')
      .eq('owner_id', userId)
      .in('status', ['new', 'read'])
      .order('created_at', { ascending: false })
      .limit(100);
    setLoading(false);
    if (error) {
      if (!['42P01', 'PGRST204'].includes(error.code || '')) {
        console.error('Public DM inbox could not be loaded:', error);
      }
      return;
    }
    setSubmissions((data || []) as PublicDmSubmission[]);
  };

  useEffect(() => {
    if (!userId) return;
    void load();
    const channel = supabase
      .channel(`public-dm-inbox:${userId}`)
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'public_dm_submissions',
        filter: `owner_id=eq.${userId}`,
      }, () => void load())
      .subscribe();
    return () => {
      void supabase.removeChannel(channel);
    };
  }, [userId]);

  const unread = submissions.filter((submission) => submission.status === 'new').length;
  useEffect(() => onUnreadChange?.(unread), [unread, onUnreadChange]);

  const filtered = useMemo(() => {
    const query = searchQuery.trim().toLowerCase();
    if (!query) return submissions;
    return submissions.filter((submission) =>
      [
        submission.guest_name,
        submission.guest_email,
        submission.subject,
        submission.company_name,
        submission.topic,
        submission.message,
      ].some((value) => value?.toLowerCase().includes(query)),
    );
  }, [searchQuery, submissions]);

  const grouped = useMemo(() => {
    const categories = new Map<string, Map<string, PublicDmSubmission[]>>();
    filtered.forEach((submission) => {
      const category = submission.primary_category || labelNames[submission.label] || 'Questions';
      const subcategory = submission.subcategory || submission.topic || 'General';
      if (!categories.has(category)) categories.set(category, new Map());
      const children = categories.get(category)!;
      children.set(subcategory, [...(children.get(subcategory) || []), submission]);
    });
    return [...categories.entries()]
      .map(([category, children]) => ({
        category,
        children: [...children.entries()]
          .map(([subcategory, items]) => ({ subcategory, items }))
          .sort((a, b) => b.items.length - a.items.length || a.subcategory.localeCompare(b.subcategory)),
        count: [...children.values()].reduce((total, items) => total + items.length, 0),
        unread: [...children.values()].flat().filter((item) => item.status === 'new').length,
      }))
      .sort((a, b) => b.unread - a.unread || b.count - a.count || a.category.localeCompare(b.category));
  }, [filtered]);

  const openSubmission = async (submission: PublicDmSubmission) => {
    const next = submission.status === 'new'
      ? { ...submission, status: 'read' as const, read_at: new Date().toISOString() }
      : submission;
    if (submission.status === 'new') {
      setSubmissions((current) => current.map((item) => item.id === submission.id ? next : item));
      await supabase
        .from('public_dm_submissions')
        .update({ status: 'read', read_at: next.read_at })
        .eq('id', submission.id)
        .eq('owner_id', userId);
    }
    onOpenConversation(next);
  };

  useEffect(() => {
    const requestedId = searchParams.get('public_dm');
    if (!requestedId || activeSubmissionId === requestedId) return;
    const requested = submissions.find((submission) => submission.id === requestedId);
    if (requested) void openSubmission(requested);
  }, [searchParams, submissions, activeSubmissionId]);

  const toggleCollapsed = (
    setter: Dispatch<SetStateAction<Set<string>>>,
    key: string,
  ) => {
    setter((current) => {
      const next = new Set(current);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  };

  if (!visible) return null;

  if (loading && submissions.length === 0) {
    return (
      <div className="flex items-center justify-center gap-2 px-4 py-6 text-sm text-gray-500">
        <Loader2 className="h-4 w-4 animate-spin" /> Loading public DMs...
      </div>
    );
  }

  if (filtered.length === 0) {
    return (
      <div className="mx-2 my-3 rounded-2xl border border-dashed border-white/10 px-4 py-7 text-center">
        <Inbox className="mx-auto mb-2 h-5 w-5 text-gray-500" />
        <p className="text-sm font-medium text-gray-400">No public DMs yet</p>
        <p className="mt-1 text-xs text-gray-600">Messages sent through your /pd link appear here in real time.</p>
      </div>
    );
  }

  return (
    <div className="space-y-2">
      <div className="mx-2 flex items-center gap-2 rounded-xl border border-blue-500/10 bg-blue-500/[0.055] px-3 py-2 text-[11px] text-blue-200/75">
        <Sparkles className="h-3.5 w-3.5" />
        <span>Public messages open as complete chat conversations.</span>
      </div>
      {grouped.map(({ category, children, count, unread: categoryUnread }) => {
        const categoryCollapsed = collapsedCategories.has(category);
        return (
          <section key={category} className="overflow-hidden rounded-[18px] border border-white/[0.055] bg-white/[0.018]">
            <button
              type="button"
              onClick={() => toggleCollapsed(setCollapsedCategories, category)}
              className="flex w-full items-center gap-2 px-3 py-2.5 text-left"
              aria-expanded={!categoryCollapsed}
            >
              <ChevronDown className={`h-3.5 w-3.5 text-gray-500 transition-transform ${categoryCollapsed ? '-rotate-90' : ''}`} />
              <span className="chat-primary-text min-w-0 flex-1 truncate text-[12px] font-bold uppercase tracking-[0.08em]">{category}</span>
              {categoryUnread > 0 && (
                <span className="flex h-5 min-w-5 items-center justify-center rounded-full bg-blue-500 px-1.5 text-[9px] font-bold text-white">{categoryUnread}</span>
              )}
              <span className="chat-tertiary-text text-[10px]">{count}</span>
            </button>
            {!categoryCollapsed && (
              <div className="border-t border-white/[0.045] pb-1">
                {children.map(({ subcategory, items }) => {
                  const subcategoryKey = `${category}:${subcategory}`;
                  const subcategoryCollapsed = collapsedSubcategories.has(subcategoryKey);
                  return (
                    <div key={subcategoryKey}>
                      <button
                        type="button"
                        onClick={() => toggleCollapsed(setCollapsedSubcategories, subcategoryKey)}
                        className="chat-secondary-text flex w-full items-center gap-2 px-4 py-2 text-left text-[11px] font-semibold"
                        aria-expanded={!subcategoryCollapsed}
                      >
                        <ChevronDown className={`h-3 w-3 transition-transform ${subcategoryCollapsed ? '-rotate-90' : ''}`} />
                        <span className="min-w-0 flex-1 truncate">{subcategory}</span>
                        <span className="chat-tertiary-text">{items.length}</span>
                      </button>
                      {!subcategoryCollapsed && items.map((submission) => (
                        <button
                          type="button"
                          key={submission.id}
                          onClick={() => void openSubmission(submission)}
                          className={`chat-list-item mx-1 flex w-[calc(100%-0.5rem)] items-center gap-3 rounded-[16px] p-3 text-left transition-all active:scale-[0.985] ${
                            activeSubmissionId === submission.id ? 'is-active' : ''
                          }`}
                        >
                          <span className="relative flex h-[46px] w-[46px] shrink-0 items-center justify-center rounded-[16px] bg-indigo-500/15 text-indigo-300">
                            <Mail className="h-4.5 w-4.5" />
                            {submission.status === 'new' && <span className="absolute right-0 top-0 h-3 w-3 rounded-full border-2 border-[#141414] bg-blue-500" />}
                          </span>
                          <span className="min-w-0 flex-1">
                            <span className="mb-1 flex items-center justify-between gap-2">
                              <span className="chat-primary-text truncate text-[14px] font-semibold">{submission.guest_name || submission.guest_email || 'Guest'}</span>
                              <span className="chat-tertiary-text shrink-0 text-[10px]">
                                {new Date(submission.created_at).toLocaleDateString('en-US', { day: '2-digit', month: 'short' })}
                              </span>
                            </span>
                            <span className="flex items-center gap-1.5">
                              <span className="chat-secondary-text min-w-0 flex-1 truncate text-[12px]">{submission.subject || submission.message}</span>
                              {submission.ai_classification_status === 'ai_verified' && <Sparkles className="h-3 w-3 shrink-0 text-blue-400" aria-label="AI checked" />}
                              {submission.urgency === 'urgent' && <span className="h-2 w-2 shrink-0 rounded-full bg-orange-400" aria-label="Urgent" />}
                            </span>
                          </span>
                        </button>
                      ))}
                    </div>
                  );
                })}
              </div>
            )}
          </section>
        );
      })}
    </div>
  );
};
